// Surah-start pages derived once at module load (1..114 → 1..604).
const START_PAGE: readonly number[] = (() => {
  const t = new Array(115).fill(0);
  const entries = Object.entries(SURAH_HEADER_MAP).sort((a, b) => Number(a[0]) - Number(b[0]));
  for (const [pageStr, surahs] of entries) {
    const page = Number(pageStr);
    for (const s of surahs) if (t[s] === 0) t[s] = page;
  }
  return t;
})();

export function pageLineCount(page: number): number {
  return PACKED[page - 1]?.length ?? 0;
}

export function lineType(page: number, line: number): MushafLineType {
  const c = PACKED[page - 1]?.[line - 1] ?? '.';
  return c === 'S' ? 'surah' : c === 'B' ? 'basmala' : 'text';
}

// Surahs whose header band is on this page, in line order.
export function pageSurahHeaders(page: number): readonly number[] {
  return SURAH_HEADER_MAP[page] ?? [];
}

// First mushaf page of a surah (0 if unknown).
export function surahStartPage(surah: number): number {
  return START_PAGE[surah] ?? 0;
}
